package cr.ac.cuc.nuevoavatar.persona5.notificacion;
import jakarta.persistence.*;import java.time.OffsetDateTime;
@Entity @Table(name="Notificacion",schema="general") public class Notificacion{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="NotificacionId")private Long id;@Column(name="Destinatarios",nullable=false,length=1000)private String destinatarios;@Column(name="Asunto",nullable=false,length=150)private String asunto;@Column(name="HtmlSanitizado",nullable=false,columnDefinition="nvarchar(max)")private String htmlSanitizado;@Column(name="Fecha",nullable=false)private OffsetDateTime fecha;@Column(name="Usuario",nullable=false,length=150)private String usuario;@Column(name="Estado",nullable=false,length=20)private String estado;@Column(name="Error",length=500)private String error;public Long getId(){return id;}public String getDestinatarios(){return destinatarios;}public String getAsunto(){return asunto;}public String getHtmlSanitizado(){return htmlSanitizado;}public OffsetDateTime getFecha(){return fecha;}public String getUsuario(){return usuario;}public String getEstado(){return estado;}public String getError(){return error;}public void datos(String d,String a,String h,String u,String e,String x){destinatarios=d;asunto=a;htmlSanitizado=h;usuario=u;estado=e;error=x;fecha=OffsetDateTime.now();}}
